const $=s=>document.querySelector(s);const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let view='training',running=false,epoch=0,history=[],logs=[],timer=null,runId=1,chapter=0;let cfg={kind:'moons',lr:.08,hidden:12,batch:32,epochs:160,seed:42,noise:.12},data,model;let runs=[];try{runs=JSON.parse(localStorage.getItem('trainlab-runs')||'[]');if(!Array.isArray(runs))runs=[]}catch{}let lastTest=null;
const names={training:['训练工作台','从数据到模型，让每一次训练都有迹可循。'],experiments:['实验记录','对比每一次尝试，找到更好的训练方向。'],data:['数据集','先理解数据，再让模型理解数据。'],llm:['大模型配置','把训练概念转化为一份可复现的配置草案。'],learn:['训练知识库','建立直觉，理解原理，然后亲手验证。']};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3200)}function log(t){logs.push({time:new Date().toLocaleTimeString('zh-CN',{hour12:false}),text:t});if(logs.length>80)logs.shift()}function init(){data=TrainEngine.dataset(cfg.kind,cfg.noise,cfg.seed);model=new TrainEngine.MLP(cfg.hidden,cfg.seed);epoch=0;lastTest=null;history=[{epoch:0,train:model.evaluate(data.train),val:model.evaluate(data.val)}];logs=[];log('数据已准备 · 280 训练 / 60 验证 / 60 测试');log(`模型初始化 · 2 → ${cfg.hidden} → 1 · seed ${cfg.seed}`)}
function stat(label,value,foot,icon,id){return `<div class="stat"><div class="stat-label">${label}</div><span class="stat-icon">${icon}</span><div class="stat-value" id="${id}">${value}</div><div class="stat-foot">${foot}</div></div>`}
function training(){return `<div class="topline"><div class="tabs"><span>实时训练</span><span>双层神经网络 MLP</span></div><span class="run-info">EXP-${String(runId).padStart(3,'0')} · 可复现训练</span></div><div class="stats">${stat('训练损失','—','Binary cross entropy','⌁','train-loss')}${stat('验证准确率','—','独立验证集 · 60 个样本','◎','val-acc')}${stat('训练轮次','0 / 160','Epoch · 完整遍历训练集','◷','epoch-value')}${stat('可训练参数',cfg.hidden*4+1,'2 输入 · tanh · 1 输出','◇','params')}</div><div class="layout"><section class="panel"><div class="panel-head"><h2>实验配置</h2><span class="badge gray">MLP</span></div><div class="config-body"><label class="field"><span>数据集</span><select id="kind"><option value="moons">双月数据 · Two Moons</option><option value="circles">同心圆 · Circles</option><option value="xor">异或分布 · XOR</option></select></label><label class="field"><span>学习率 <span class="muted">Learning rate</span></span><select id="lr"><option value="0.005">0.005 · 小步探索</option><option value="0.02">0.02 · 稳步更新</option><option value="0.08">0.08 · 推荐起点</option><option value="0.3">0.3 · 更大步长</option><option value="2">2.0 · 观察震荡</option></select><small>每次参数更新的步长</small></label><div class="split"><label class="field"><span>隐藏单元</span><select id="hidden"><option>4</option><option>12</option><option>24</option><option>48</option></select></label><label class="field"><span>Batch size</span><select id="batch"><option>16</option><option>32</option><option>64</option><option>280</option></select></label></div><div class="split"><label class="field"><span>训练轮次</span><input id="epochs" type="number" min="10" max="1000" step="10" value="${cfg.epochs}"></label><label class="field"><span>随机种子</span><input id="seed" type="number" min="0" max="99999" value="${cfg.seed}"></label></div><div class="divider"></div><button class="button lime" id="start">▷ 开始训练</button><button class="button" id="reset">↻ 重置实验</button><div class="config-note">真实梯度计算，在你的浏览器运行。<br>无需 GPU，不会产生云端训练费用。</div></div></section><div class="right-column"><section class="panel"><div class="panel-head"><h2>损失曲线 <span id="status" class="badge gray">准备就绪</span></h2><div class="legend"><span><i style="background:#8571dc"></i>训练集</span><span><i style="background:#6cbaa4"></i>验证集</span></div></div><div class="chart-wrap"><canvas id="loss-chart" aria-label="训练和验证损失随训练轮次变化"></canvas></div><div class="under-chart"><span>LOSS / 交叉熵</span><span>EPOCH</span></div></section><div class="bottom-grid"><section class="panel"><div class="panel-head"><h2>决策边界</h2><small>实时推理</small></div><div class="decision-wrap"><canvas id="boundary" aria-label="二维样本及模型预测概率"></canvas><div class="mini-note">紫色 / 绿色代表两类样本，底色是模型预测。</div></div></section><section class="panel"><div class="panel-head"><h2>训练日志</h2><small id="log-label">等待启动</small></div><div class="log" id="logs"></div></section></div></div></div><div class="lesson-banner"><div class="lesson-icon">✧</div><div><strong>为什么训练损失下降，模型却没有变好？</strong><p>认识过拟合，以及训练集、验证集和测试集各自的作用。</p></div><button data-chapter="2">学习这个概念 ↗</button></div>`}
function render(){const [title,sub]=names[view];$('#page-heading').textContent=title;$('#breadcrumb').textContent=title;$('#page-subtitle').textContent=sub;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#run-count').textContent=runs.length;$('#content').innerHTML=({training,experiments,data:dataView,llm,learn}[view])();bind();if(view==='training'){for(const key of ['kind','lr','hidden','batch'])$('#'+key).value=cfg[key];update();}if(view==='data')drawBoundary('data-chart',false)}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;location.hash=view;render()});document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{chapter=+b.dataset.chapter;view='learn';render()});if(view==='training'){$('#start').onclick=toggle;$('#reset').onclick=()=>{stop();runId++;init();render();toast('已重置为相同种子的初始状态')};for(const key of ['kind','lr','hidden','batch','epochs','seed'])$('#'+key).onchange=e=>{let n=key==='kind'?e.target.value:+e.target.value;if(key==='epochs'&&(!Number.isInteger(n)||n<10||n>1000)||key==='seed'&&(!Number.isInteger(n)||n<0||n>99999)){e.target.value=cfg[key];toast('请输入范围内的整数');return}stop();cfg[key]=n;runId++;init();render()}}if(view==='data')$('#download-data').onclick=()=>download('trainlab-dataset.csv','split,x1,x2,label\n'+['train','val','test'].flatMap(k=>data[k].map(d=>`${k},${d.x[0]},${d.x[1]},${d.y}`)).join('\n'),'text/csv');if(view==='llm'){document.querySelectorAll('.llm-input').forEach(x=>x.oninput=updateLLM);$('#download-config').onclick=()=>download('lora-config-draft.json',JSON.stringify(llmConfig(),null,2));updateLLM()}document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>toast(b.dataset.answer==='yes'?'回答正确：保留测试集，避免调参时的信息泄漏。':'再想一下：频繁查看测试结果会影响你的选择。'));}
function toggle(){if(running){stop();log('训练已暂停，可继续');update();return}if(epoch>=cfg.epochs){runId++;init()}running=true;lastTest=null;log(`训练启动 · SGD · lr ${cfg.lr} · batch ${cfg.batch}`);timer=setInterval(()=>{for(let k=0;k<2&&epoch<cfg.epochs;k++){model.trainEpoch(data.train,cfg.lr,cfg.batch);epoch++;history.push({epoch,train:model.evaluate(data.train),val:model.evaluate(data.val)})}if(epoch%20===0)log(`epoch ${epoch} · loss ${history.at(-1).train.loss.toFixed(4)} · val ${history.at(-1).val.loss.toFixed(4)}`);if(epoch>=cfg.epochs){stop();lastTest=model.evaluate(data.test);log(`训练完成 · 测试准确率 ${(lastTest.accuracy*100).toFixed(1)}%`);saveRun();toast('训练完成，结果已加入实验记录')}update()},65);update()}
function stop(){running=false;clearInterval(timer);timer=null}function saveRun(){const last=history.at(-1);runs.unshift({id:Date.now(),name:`MLP · ${cfg.kind}`,cfg:{...cfg},train:last.train,val:last.val,test:lastTest,epochs:epoch,at:new Date().toISOString()});runs=runs.slice(0,30);try{localStorage.setItem('trainlab-runs',JSON.stringify(runs))}catch{toast('浏览器存储不可用，请导出实验保存')}$('#run-count').textContent=runs.length}
function update(){if(view!=='training')return;const last=history.at(-1);$('#train-loss').textContent=last.train.loss.toFixed(4);$('#val-acc').textContent=(last.val.accuracy*100).toFixed(1)+'%';$('#epoch-value').innerHTML=`${epoch}<span style="font-size:15px;color:#a0a7b2;font-weight:400"> / ${cfg.epochs}</span>`;$('#start').textContent=running?'Ⅱ 暂停训练':epoch>=cfg.epochs?'▷ 再次训练':epoch?'▷ 继续训练':'▷ 开始训练';$('#status').textContent=running?'训练中':epoch>=cfg.epochs?'已完成':epoch?'已暂停':'准备就绪';$('#status').className='badge '+(running||epoch>=cfg.epochs?'green':'gray');$('#log-label').textContent=running?'实时更新':'浏览器 CPU';$('#logs').innerHTML=logs.map(l=>`<div class="log-line"><span>${l.time}</span>${escapeHTML(l.text)}</div>`).join('');$('#logs').scrollTop=$('#logs').scrollHeight;document.querySelectorAll('.config-body input,.config-body select').forEach(el=>el.disabled=running);drawLoss();drawBoundary('boundary',true)}
function canvas(id){const c=$('#'+id);if(!c)return null;const rect=c.getBoundingClientRect(),dpr=window.devicePixelRatio||1;c.width=Math.max(1,rect.width*dpr);c.height=Math.max(1,rect.height*dpr);let ctx=c.getContext('2d');ctx.scale(dpr,dpr);return{ctx,w:rect.width,h:rect.height}}
function drawLoss(){let c=canvas('loss-chart');if(!c)return;let{ctx,w,h}=c;let pad={l:42,r:15,t:16,b:26},pw=w-pad.l-pad.r,ph=h-pad.t-pad.b;let max=Math.max(.8,...history.flatMap(x=>[x.train.loss,x.val.loss]))*1.1;ctx.font='10px -apple-system,sans-serif';for(let i=0;i<=4;i++){let y=pad.t+ph*i/4;ctx.strokeStyle='#eef0f4';ctx.setLineDash([3,4]);ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke();ctx.fillStyle='#a0a7b3';ctx.fillText((max*(1-i/4)).toFixed(2),2,y+4);ctx.fillText(String(Math.round(cfg.epochs*i/4)),pad.l+pw*i/4-5,h-3)}ctx.setLineDash([]);for(const [key,color]of[['train','#8571dc'],['val','#6cbaa4']]){ctx.strokeStyle=color;ctx.lineWidth=2.3;ctx.beginPath();history.forEach((d,i)=>{const x=pad.l+pw*d.epoch/cfg.epochs,y=pad.t+ph*(1-d[key].loss/max);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}if(epoch===0){ctx.fillStyle='#b2b7c1';ctx.textAlign='center';ctx.fillText('开始训练，观察模型如何一步步学习',pad.l+pw/2,pad.t+ph/2);ctx.textAlign='left'}}
function drawBoundary(id,predict){let c=canvas(id);if(!c)return;let{ctx,w,h}=c;const range=1.35;for(let y=0;y<h;y+=5)for(let x=0;x<w;x+=5){const p=predict?model.forward([(x/w*2-1)*range,(1-y/h*2)*range]).p:.5;ctx.fillStyle=`rgb(${Math.round(232-p*29)},${Math.round(225+p*18)},${Math.round(247-p*18)})`;ctx.fillRect(x,y,5,5)}ctx.strokeStyle='#ffffff66';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(w/2,0);ctx.lineTo(w/2,h);ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.stroke();for(const d of data.train){ctx.beginPath();ctx.arc((d.x[0]/range+1)*w/2,(1-d.x[1]/range)*h/2,2.5,0,2*Math.PI);ctx.fillStyle=d.y?'#399d84':'#7c60cc';ctx.fill();ctx.strokeStyle='#ffffffb0';ctx.lineWidth=.6;ctx.stroke()}}
function experiments(){return `<section class="panel"><div class="panel-head"><h2>已完成的实验</h2><span class="badge gray">当前设备 · 最近 30 次</span></div>${runs.length?`<div class="table-wrap"><table><thead><tr><th>实验</th><th>学习率 / 隐藏单元</th><th>训练损失</th><th>验证准确率</th><th>测试准确率</th><th>轮次</th></tr></thead><tbody>${runs.map(r=>`<tr><td><strong>${escapeHTML(r.name)}</strong><br><small class="muted">${new Date(r.at).toLocaleString('zh-CN')}</small></td><td>${r.cfg.lr} / ${r.cfg.hidden}</td><td>${r.train.loss.toFixed(4)}</td><td>${(r.val.accuracy*100).toFixed(1)}%</td><td>${(r.test.accuracy*100).toFixed(1)}%</td><td>${r.epochs}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">还没有完成的实验。<br>在训练工作台启动一次训练，就会在这里留下记录。<div class="actions" style="justify-content:center"><button class="button primary" data-view="training">开始第一个实验</button></div></div>'}</section><div class="callout">建议一次只改变一个参数。对比时保持数据划分和随机种子一致；测试集只用于最终报告，不要根据测试表现反复调参。</div>`}
function dataView(){return `<p class="section-note">当前数据由固定随机种子生成。共 400 个二维分类样本，无外部数据上传。</p><div class="grid2"><section class="panel"><div class="panel-head"><h2>${{moons:'双月数据',circles:'同心圆',xor:'异或分布'}[cfg.kind]}</h2><span class="badge">合成数据</span></div><div class="decision-wrap"><canvas id="data-chart" style="height:310px" aria-label="训练样本散点图"></canvas><p class="mini-note">显示训练集 280 个样本 · 特征 x₁ 与 x₂ · 标签 0 / 1</p></div></section><section class="panel"><div class="panel-head"><h2>数据划分</h2><span class="badge gray">Seed ${cfg.seed}</span></div><div class="text-body"><div class="data-split"><span style="width:70%;background:#8b78d9"></span><span style="width:15%;background:#81bba6"></span><span style="width:15%;background:#c9d1de"></span></div><p>训练集 <b>70% · 280</b> — 计算梯度并更新参数</p><p>验证集 <b>15% · 60</b> — 观察泛化，指导参数选择</p><p>测试集 <b>15% · 60</b> — 训练结束后报告表现</p><button class="button" id="download-data">↓ 下载 CSV 数据</button><div class="mini-note">在训练工作台切换数据集和种子。企业数据通常还需按用户、文档或时间分组切分，以避免泄漏。</div></div></section></div>`}
function llmConfig(){return{purpose:'configuration_draft_not_submitted',base_model:$('#base-model').value,method:$('#method').value,learning_rate:+$('#llm-lr').value,num_train_epochs:+$('#llm-epochs').value,per_device_train_batch_size:+$('#micro').value,gradient_accumulation_steps:+$('#accum').value,world_size:+$('#gpus').value,lora_r:+$('#rank').value,lora_alpha:2*(+$('#rank').value),max_length:+$('#seq').value,seed:42,validation_split:.1,notes:'示例配置，训练前确认模型标识、数据模板、硬件精度和目标模块；未连接训练后端。'}}
function llm(){return `<div class="callout" style="margin-top:0">配置学习模式：生成 LoRA / QLoRA 配置草案。尚未连接 GPU 集群，不会提交云端训练任务。</div><div class="grid2"><section class="panel"><div class="panel-head"><h2>微调任务配置</h2><span class="badge">SFT</span></div><div class="text-body"><label class="field"><span>基础模型标识</span><input class="llm-input" id="base-model" value="your-org/your-base-model"></label><div class="split"><label class="field"><span>训练方法</span><select class="llm-input" id="method"><option>LoRA</option><option>QLoRA</option></select></label><label class="field"><span>学习率</span><select class="llm-input" id="llm-lr"><option value="0.0001">1e-4</option><option value="0.0002">2e-4</option><option value="0.00005">5e-5</option></select></label><label class="field"><span>每卡 Micro batch</span><select class="llm-input" id="micro"><option>1</option><option>2</option><option>4</option><option>8</option></select></label><label class="field"><span>梯度累积</span><select class="llm-input" id="accum"><option>8</option><option>16</option><option>32</option></select></label><label class="field"><span>数据并行卡数</span><select class="llm-input" id="gpus"><option>1</option><option>2</option><option>4</option><option>8</option></select></label><label class="field"><span>LoRA Rank</span><select class="llm-input" id="rank"><option>16</option><option>8</option><option>32</option><option>64</option></select></label><label class="field"><span>最大序列长度</span><select class="llm-input" id="seq"><option>2048</option><option>4096</option><option>8192</option></select></label><label class="field"><span>训练轮次</span><select class="llm-input" id="llm-epochs"><option>3</option><option>1</option><option>2</option></select></label></div><div class="callout" id="effective"></div><button class="button primary" id="download-config">↓ 导出配置草案</button></div></section><section class="panel"><div class="panel-head"><h2>配置预览</h2><small>JSON</small></div><div class="text-body"><pre class="json" id="json-config"></pre><p style="font-size:13px">LoRA 训练少量新增的低秩参数；QLoRA 进一步量化冻结的基础权重。显存还受激活、优化器状态、序列长度和具体实现影响，不能只按参数量判断。</p><button class="inline-link" data-chapter="4">学习微调方法与显存原理</button></div></section></div>`}
function updateLLM(){const c=llmConfig();$('#effective').textContent=`有效 Batch size = ${c.per_device_train_batch_size} × ${c.gradient_accumulation_steps} × ${c.world_size} = ${c.per_device_train_batch_size*c.gradient_accumulation_steps*c.world_size} 条样本 / 更新`;$('#json-config').textContent=JSON.stringify(c,null,2)}
const chapters=[
['01','训练在做什么','训练，是用数据逐步调整模型参数。','<p>把模型想象成一个可调的函数：输入数据 x，输出预测 fθ(x)。损失函数衡量预测与目标的差距，优化器根据梯度更新参数 θ。</p><div class="formula">预测 → 计算损失 → 反向传播 → 更新参数 → 重复</div><h3>参数与超参数</h3><p>权重和偏置由训练学习；学习率、批次大小、网络宽度和训练轮次由人设定。当前实验是 2 个输入、一个 tanh 隐藏层和一个 sigmoid 输出的二分类网络。</p><h3>动手观察</h3><p>保持默认参数启动训练。比较训练开始和结束时的决策边界：模型逐渐把两类数据分开，而不是记住屏幕上的颜色。</p>'],
['02','梯度与学习率','梯度给出局部上升方向，训练通常沿反方向移动。','<div class="formula">θ ← θ − η ∇θ L</div><p>η 是学习率。它太小可能收敛缓慢，太大可能跨过较优区域或导致震荡。反向传播用链式法则高效计算每个参数对损失的影响。</p><h3>批次与轮次</h3><p>Batch 是一次梯度估计使用的样本；Epoch 是完整遍历一次训练集。本平台用小批次 SGD，在每轮内打乱训练数据。280 个样本、Batch 32 时，每轮有 9 次更新。</p><div class="callout">实验：固定 seed 42，分别尝试 0.005、0.08 与 2.0。关注速度和稳定性，而不是假设学习率越大越好。</div>'],
['03','泛化与过拟合','训练集表现好，不等于对新数据表现好。','<p>训练集参与参数更新；验证集用于选择参数和模型；测试集在方案确定后用于最终评估。若不断查看测试结果来调参，测试集也会变成隐含的验证集。</p><h3>如何判断过拟合</h3><p>训练损失持续下降，而验证损失开始回升，是一个典型信号。可尝试增加合适的数据、降低模型容量、正则化或早停。单次曲线不是充分证明，还应检查样本量、数据分布与多个种子。</p><h3>企业数据尤其要留意</h3><p>同一用户、同一文档或近重复内容跨集合出现，可能让指标虚高。按业务对象或时间分组划分，通常比直接随机分行更合理。</p><div class="quiz">自测：调参时应该频繁使用测试集吗？<br><button class="button" data-answer="no">应该，数据越多越好</button><button class="button" data-answer="yes">不应该，保留最终评估</button></div>'],
['04','大模型训练全景','预训练学习基础分布，后训练塑造任务行为。','<h3>预训练与 Transformer</h3><p>自回归语言模型通常通过预测下一个 token 学习文本分布。Transformer 通过注意力机制聚合上下文信息；token 是分词后的单位，不等于一个汉字或一个英文单词。</p><h3>SFT 监督微调</h3><p>使用输入和高质量目标输出的示范数据，让已有模型适应指令、格式或领域任务。需正确应用聊天模板，并检查哪些 token 参与损失。</p><h3>偏好优化</h3><p>RLHF 常通过偏好训练奖励模型，再优化策略；DPO 直接利用优选与劣选回答优化偏好目标。偏好更高并不自动代表事实更准确。</p><div class="callout">需要更新知识时，也应评估 RAG：检索资料后放入上下文，通常无需改变模型参数。微调更适合塑造行为和任务能力。</div>'],
['05','LoRA 与训练资源','以更少可训练参数适配模型。','<div class="formula">W′ = W + (α / r) BA</div><p>常见 LoRA 形式冻结原权重 W，训练低秩矩阵 A 与 B，r 为秩。QLoRA 使用量化的冻结基础权重，并训练适配器；并不是所有训练计算都在 4 bit 下进行。</p><h3>有效批次大小</h3><div class="formula">每卡 micro batch × 梯度累积步数 × 数据并行卡数</div><p>这是等批次数据并行场景下每次更新处理的样本数；可变序列长度下，还要记录实际有效 token 数。</p><h3>显存为什么不够</h3><p>显存包括权重、梯度、优化器状态、激活和临时缓冲。缩短序列、减小 micro batch、使用激活检查点、参数分片或适配器微调，都可能降低需求，但会有速度或能力方面的取舍。</p>'],
['06','评估与公司实践','先定义成功，再决定训练什么。','<p>先明确业务任务、错误成本和验收指标。分类可报告 precision、recall、F1 和混淆矩阵；生成任务还需要任务正确率、格式遵循、事实性与人工盲评。</p><h3>一次可靠实验的记录</h3><ul><li>基础模型与 tokenizer 的版本</li><li>数据版本、去重规则、划分方式</li><li>代码、依赖、seed、全部训练参数</li><li>训练曲线、验证指标与最终测试结果</li><li>检查点、资源消耗与失败样本</li></ul><h3>四周学习路线</h3><p>第 1 周：跑通本平台，理解梯度与泛化。第 2 周：用 PyTorch 复现小模型。第 3 周：整理业务 SFT 数据，完成一次小规模 LoRA。第 4 周：建立固定评测集，对比基线、RAG 和微调。</p>']
];
function learn(){let c=chapters[chapter];return `<div class="course"><section class="panel chapters">${chapters.map((x,i)=>`<button data-chapter="${i}" class="${chapter===i?'active':''}">${x[0]} &nbsp; ${x[1]}</button>`).join('')}</section><article class="panel article"><div class="eyebrow">TRAINING FUNDAMENTALS / ${c[0]}</div><h2>${c[1]}</h2><p style="color:#303846;font-weight:550">${c[2]}</p>${c[3]}<div class="divider"></div><p style="font-size:13px">延伸阅读：<a href="https://docs.pytorch.org/tutorials/beginner/basics/optimization_tutorial.html" target="_blank" rel="noopener">PyTorch 训练循环</a> · <a href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noopener">Transformer</a> · <a href="https://huggingface.co/docs/peft/package_reference/lora" target="_blank" rel="noopener">LoRA 文档</a> · <a href="https://arxiv.org/abs/2305.14314" target="_blank" rel="noopener">QLoRA</a> · <a href="https://arxiv.org/abs/2305.18290" target="_blank" rel="noopener">DPO</a></p><div class="actions"><button class="button primary" data-view="training">在实验中验证</button>${chapter<5?`<button class="button" data-chapter="${chapter+1}">下一章</button>`:''}</div></article></div>`}
function download(name,text,type='application/json'){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}$('#export').onclick=()=>download('trainlab-experiment.json',JSON.stringify({schema_version:1,engine:'MLP tanh sigmoid SGD',config:cfg,epoch,history,weights:model.weights(),test:lastTest,saved_runs:runs},null,2));window.addEventListener('resize',()=>{if(view==='training'){drawLoss();drawBoundary('boundary',true)}if(view==='data')drawBoundary('data-chart',false)});init();if(names[location.hash.slice(1)])view=location.hash.slice(1);render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'get_training_state',title:'读取当前训练状态',description:'读取当前浏览器实验的配置、轮次、训练与验证指标，不启动训练。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected empty object');return{running,epoch,config:{...cfg},metrics:history.at(-1),completed_runs:runs.length}}},{name:'start_training',title:'启动当前小模型训练',description:'使用界面当前配置，在浏览器 CPU 启动或继续 MLP 训练；已完成时重新训练，不提交云端任务。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected empty object');if(running)throw new Error('Training is already running');view='training';render();toggle();return{running,epoch,config:{...cfg}}}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}}
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(names[next]&&view!==next){view=next;render()}});
